	public override int PitToTileSetIDSubFunction(TileGrid tileGrid, int tileRow, int tileCol, int pitTilesAbove = 0, int pitTilesBelow = 0)
	{
		if (pitTilesAbove == 0 && pitTilesBelow == 0)
		{
			return platformTopWallTiles.GetRandomValue();
		}
		MapOrdinalDirections mapOrdinalDirections = TileSet.CheckAdjacentTiles(tileRow, tileCol, tileGrid, (Tile t) => t.terrain == Tile.TerrainType.Pit);
		switch (pitTilesAbove)
		{
		case 0:
			if (AdjTileTest.WallNorth.Test(tileGrid, tileRow, tileCol))
			{
				return platformWallTransitionTiles.GetRandomValue();
			}
			return platformTopWallTiles.GetRandomValue();
		case 1:
			return platformMidWallTiles.GetRandomValue();
		case 2:
			return platformLowerWallTiles.GetRandomValue();
		default:
		{
			MapOrdinalDirections mapOrdinalDirections2 = MapOrdinalDirections.None;
			if (tileGrid.IsValidTile(tileRow - 1, tileCol))
			{
				mapOrdinalDirections2 = TileSet.CheckAdjacentTiles(tileRow - 1, tileCol, tileGrid, (Tile t) => t.terrain == Tile.TerrainType.Pit);
			}
			bool flag = !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.East) && !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.NorthEast);
			bool flag2 = !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.West) && !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.NorthWest);
			if (pitTilesAbove == 3)
			{
				if (flag && !mapOrdinalDirections.HasFlag(MapOrdinalDirections.East))
				{
					return platformPitTopRightCornerTile;
				}
				if (flag2 && !mapOrdinalDirections.HasFlag(MapOrdinalDirections.West))
				{
					return platformPitTopLeftCornerTile;
				}
				return platformPitTransitionTiles.GetRandomValue();
			}
			bool flag3 = tileGrid.IsValidTile(tileRow - 3, tileCol + 1) && (tileGrid[tileRow - 3, tileCol + 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 3, tileCol + 1].overlay != Tile.OverlayType.None);
			if (tileGrid.IsValidTile(tileRow - 3, tileCol - 1) && (tileGrid[tileRow - 3, tileCol - 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 3, tileCol - 1].overlay != Tile.OverlayType.None))
			{
				return pitLeftWallTiles.GetRandomValue();
			}
			if (flag3)
			{
				return pitRightWallTiles.GetRandomValue();
			}
			int num = tileGrid.CountTilesInDir(tileRow, tileCol - 1, (Tile t) => t.terrain == Tile.TerrainType.Pit, MapOrdinalDirections.North, excludeFirstTile: false);
			int num2 = tileGrid.CountTilesInDir(tileRow, tileCol + 1, (Tile t) => t.terrain == Tile.TerrainType.Pit, MapOrdinalDirections.North, excludeFirstTile: false);
			if (pitTilesAbove > 3 && num2 == 4)
			{
				return platWallToPitBotLeftCornerTile;
			}
			if (pitTilesAbove > 3 && num == 4)
			{
				return platWallToPitBotRightCornerTile;
			}
			return pitTiles.GetRandomValue();
		}
		}
	}
